CREATE FUNCTION public.limit_members() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(237); IF NEW.role='admin' AND (SELECT count(*) FROM public.user_roles WHERE role='admin')>=6 THEN RAISE EXCEPTION 'Maximum six invited administrators'; END IF; RETURN NEW; END $$;
CREATE TRIGGER member_limit BEFORE INSERT ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.limit_members();
CREATE FUNCTION public.store_tmdb_movie(payload jsonb) RETURNS public.movies LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.movies; genre jsonb; gid uuid; BEGIN INSERT INTO public.movies(tmdb_id,title,original_title,overview,poster_path,backdrop_path,release_date,runtime,metadata_updated_at) VALUES((payload->>'tmdb_id')::integer,payload->>'title',payload->>'original_title',coalesce(payload->>'overview',''),payload->>'poster_path',payload->>'backdrop_path',(payload->>'release_date')::date,(payload->>'runtime')::integer,now()) ON CONFLICT(tmdb_id) DO UPDATE SET title=excluded.title,original_title=excluded.original_title,overview=excluded.overview,poster_path=excluded.poster_path,backdrop_path=excluded.backdrop_path,release_date=excluded.release_date,runtime=excluded.runtime,metadata_updated_at=now() RETURNING * INTO result; DELETE FROM public.movie_genres WHERE movie_id=result.id; FOR genre IN SELECT * FROM jsonb_array_elements(payload->'genres') LOOP INSERT INTO public.genres(tmdb_genre_id,name) VALUES((genre->>'id')::integer,genre->>'name') ON CONFLICT(tmdb_genre_id) DO UPDATE SET name=excluded.name RETURNING id INTO gid; INSERT INTO public.movie_genres(movie_id,genre_id) VALUES(result.id,gid) ON CONFLICT DO NOTHING; END LOOP; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.store_tmdb_movie(jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.store_tmdb_movie(jsonb) TO service_role;